     1→import type Phaser from 'phaser';
     2→import { supabase } from '../utils/supabase';
     3→import { getBattleLeaderboard, type BattleRecordEntry } from '../utils/battleLeaderboard';
     4→import { getBattleTier } from '../utils/battleTier';
     5→import BaseScene from './BaseScene';
     6→
     7→export default class BattleLeaderboardScene extends BaseScene {
     8→  private leaderboardEntries: BattleRecordEntry[] = [];
     9→  private leaderboardTexts: Phaser.GameObjects.GameObject[] = [];
    10→  private loadingText?: Phaser.GameObjects.Text;
    11→  private currentUserRank: {
    12→    rank: number;
    13→    totalWins: number;
    14→    winRate: number;
    15→    ratingPoints: number;
    16→    friendlyWins: number;
    17→    friendlyLosses: number;
