    24→  }
    25→
    26→  preload() {
    27→    if (!this.textures.exists('background2')) {
    28→      this.load.image('background2', 'assets/backgrounds/background2.webp');
    29→    }
    30→  }
    31→
    32→  create() {
    33→    super.create();
