    58→    const backBtn = this.add.text(200, 565, '← 대전 모드', {
    59→      fontSize: '18px',
    60→      color: '#aaaaaa',
    61→      stroke: '#000',
    62→      strokeThickness: 3,
    63→    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    64→    backBtn.on('pointerover', () => backBtn.setColor('#ffffff'));
    65→    backBtn.on('pointerout', () => backBtn.setColor('#aaaaaa'));
    66→    backBtn.on('pointerdown', () => this.scene.start('BattleMatchScene'));
