   391→  private async onRankedMatchFound(match: MatchResult) {
   392→    if (!match.roomCode || match.isHost === null || !match.opponentId) return;
   393→    this.isRanked = true;
   394→    this.isMatchmaking = false;
   395→
   396→    // 대기열에서 제거 (fire-and-forget)
   397→    cancelMatchmaking(this.userId).catch(() => {});
   398→
   399→    await this.handleRankedJoin(match.roomCode, match.isHost, match.opponentId);
   400→  }
