   648→    // ── 상대 캐릭터 (오른쪽) ─────────────────────────────────────
   649→    this.ui(this.add.rectangle(304, 280, 92, 104, 0x330000, 0.7)
   650→      .setStrokeStyle(2, 0xff4444));
   651→
   652→    // 항상 플레이스홀더 먼저 생성 — updateOpponentCharDisplay가 이 객체를 기준으로 업데이트
   653→    this.opponentCharPlaceholder = this.ui(this.add.text(304, 280, '?', {
