   744→    // CHAR_ANNOUNCE: 채널 연결 직후 상대 캐릭터 자동 수신
   745→    this.battleChannel.onEvent(BattleEvent.CHAR_ANNOUNCE, (payload) => {
   746→      if (payload.characterId && payload.characterId !== this.opponentCharId) {
