// ── 정보 카드 (캐릭터 좌측 | 랭크 우측) ──────────────────────
const def = getCharacterDef(getSafeSelectedCharacter());
const stars = def.grade === 'UR' ? '★★★'
  : def.grade === 'SR' ? '★★'
  : def.grade === 'R'  ? '★'
  : def.grade;

this.ui(this.add.rectangle(200, 155, 374, 100, 0x0d1b2a, 0.9)
  .setStrokeStyle(1, 0x334466));

// 구분선
const divGfx = this.add.graphics();
divGfx.lineStyle(1, 0x334466, 0.8);
divGfx.lineBetween(203, 110, 203, 200);
this.ui(divGfx);

// 캐릭터 이미지
if (this.textures.exists(def.imageKey)) {
  this.ui(this.add.image(62, 153, def.imageKey).setDisplaySize(50, 70));
}
this.ui(this.add.text(95, 132, def.name, {
  fontSize: '15px', color: '#ffffff', fontStyle: 'bold',
  stroke: '#000', strokeThickness: 3,
}).setOrigin(0, 0.5));
this.ui(this.add.text(95, 153, stars, {
  fontSize: '14px', color: def.gradeColor,
  stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));
this.ui(this.add.text(95, 172, def.grade !== '등급외' ? def.grade : '등급외', {
  fontSize: '11px', color: '#888888',
  stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));

// 랭크 뱃지 (우측)
this.ui(this.add.text(295, 115, '내 랭크', {
  fontSize: '10px', color: '#666666', stroke: '#000', strokeThickness: 2,
}).setOrigin(0.5));
this.rankBadgeImg = this.ui(
  this.add.image(240, 153, 'rank_alpha').setDisplaySize(36, 36).setAlpha(0),
);
this.rankBadgeNameTxt = this.ui(this.add.text(266, 137, '---', {
  fontSize: '13px', color: '#666666', stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));
this.rankBadgeRpTxt = this.ui(this.add.text(266, 155, '···', {
  fontSize: '12px', color: '#555555', stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));
this.rankBadgeRankTxt = this.ui(this.add.text(266, 172, '', {
  fontSize: '11px', color: '#666666', stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));

// 캐시된 데이터가 있으면 즉시 반영
if (this.cachedMyRp !== null) {
  this.updateRankBadge(this.cachedMyRp, this.cachedMyRank);
}

// ── 캐릭터 선택 버튼 ─────────────────────────────────────────
const charBtn = this.ui(this.add.rectangle(200, 228, 374, 40, 0x1a2a3a));
charBtn.setStrokeStyle(1, 0x4466aa);
this.ui(this.add.text(200, 228, '👤 캐릭터 선택', {
  fontSize: '16px', color: '#88aadd', fontStyle: 'bold',
  stroke: '#000', strokeThickness: 3,
}).setOrigin(0.5));
charBtn.setInteractive({ useHandCursor: true });
charBtn.on('pointerover', () => charBtn.setFillStyle(0x253a4a));
charBtn.on('pointerout', () => charBtn.setFillStyle(0x1a2a3a));
charBtn.on('pointerdown', () => {
  this.scene.start('CharacterSelectScene', { returnScene: 'BattleMatchScene' });
});

// ── 랭크 매칭 버튼 ───────────────────────────────────────────
const rankedBtn = this.ui(this.add.rectangle(200, 284, 300, 60, 0x7a5c00));
rankedBtn.setStrokeStyle(3, 0xFFD700);
this.ui(this.add.text(200, 284, '🎖️ 랭크 매칭', {
  fontSize: '24px', color: '#FFD700', fontStyle: 'bold',
  stroke: '#000', strokeThickness: 4,
}).setOrigin(0.5));
rankedBtn.setInteractive({ useHandCursor: true });
rankedBtn.on('pointerover', () => rankedBtn.setFillStyle(0xa07a00));
rankedBtn.on('pointerout', () => rankedBtn.setFillStyle(0x7a5c00));
rankedBtn.on('pointerdown', () => this.startRankedMatchmaking());

// ── 친선전 버튼 (좌우 나란히) ─────────────────────────────────
this.ui(this.add.text(200, 347, '─── 친선전 (RP 없음) ───', {
  fontSize: '13px', color: '#888888',
  stroke: '#000', strokeThickness: 2,
}).setOrigin(0.5));

const createBtn = this.ui(this.add.rectangle(100, 392, 175, 52, 0xc0392b));
createBtn.setStrokeStyle(2, 0xffffff);
this.ui(this.add.text(100, 392, '🏠 방 만들기', {
  fontSize: '17px', color: '#ffffff', fontStyle: 'bold',
  stroke: '#000', strokeThickness: 3,
}).setOrigin(0.5));
createBtn.setInteractive({ useHandCursor: true });
createBtn.on('pointerover', () => createBtn.setFillStyle(0xe74c3c));
createBtn.on('pointerout', () => createBtn.setFillStyle(0xc0392b));
createBtn.on('pointerdown', () => this.handleCreateRoom());

const joinBtn = this.ui(this.add.rectangle(300, 392, 175, 52, 0x2471a3));
joinBtn.setStrokeStyle(2, 0xffffff);

