    37→  leaderboard: BattleRecordEntry[];
    38→  currentUserRank: {
    39→    rank: number;
    40→    totalWins: number;
    41→    winRate: number;
    42→    ratingPoints: number;
    43→    friendlyWins: number;
    44→    friendlyLosses: number;
