    48→
    49→/** 세션 취득 공통 헬퍼 — 없으면 익명 로그인 후 반환 */
    50→async function getOrCreateSession() {
    51→  let { data: { session } } = await supabase.auth.getSession();
    52→  if (!session) {
    53→    const { data: authData } = await supabase.auth.signInAnonymously();
    54→    session = authData.session;
    55→  }
    56→  return session;
    57→}
    58→
    59→/**
    60→ * 대전 결과를 서버에 제출
    61→ * opponentId: 상대 유저 UUID (RP 차이 기반 변동 계산에 사용)
    62→ */
