    64→  result: BattleResult,
    65→  opponentId?: string,
    66→  isRanked: boolean = true,
    67→): Promise<SubmitBattleResultResponse> {
    68→  const session = await getOrCreateSession();
    69→
    70→  const { data, error } = await supabase.functions.invoke('battle-result-submit', {
