      const fallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement) - POOP_CONFIG.rainbow.speedReduction;
      rainbowPoop.body.velocity.y = fallSpeed;
