let playerTexturePrefix = '';
if (CHARS_WITH_SPRITES.includes(this.selectedCharId)) {
  playerTexturePrefix = `${this.selectedCharId}_`;
}
// 등급 각성 패시브: ★1 R+5/SR+10/UR+15, ★2 R+10/SR+15/UR+20
