   351→  private endBattle(result: BattleResult) {
   352→    if (this.battleFinished) return;
   353→    this.battleFinished = true;
   354→
   355→    if (this.disconnectTimer) {
   356→      clearTimeout(this.disconnectTimer);
   357→      this.disconnectTimer = null;
   358→    }
   359→
   360→    this.hideDisconnectWarning();
   361→
   362→    // 모든 결과에서 타이머 정리 (LOSE 시에도 불필요한 콜백 방지)
   363→    if (this.scoreUpdateTimer) this.scoreUpdateTimer.remove();
   364→    if (this.survivalTimerEvent) this.survivalTimerEvent.remove();
   365→
   366→    if (result === BattleResult.WIN || result === BattleResult.DISCONNECT) {
   367→      this.gameOver = true;
   368→      this.physics.pause();
   369→      this.sound.stopAll();
   370→    }
   371→
   372→    this.time.delayedCall(1000, () => {
   373→      this.scene.start('BattleResultScene', {
   374→        result,
   375→        roomCode: this.roomCode,
   376→        userId: this.battleUserId,
   377→        opponentId: this.opponentId,
   378→        isRanked: this.isRanked,
   379→      });
   380→    });
   381→  }
   382→
   383→  shutdown() {
   384→    if (this.scoreUpdateTimer) this.scoreUpdateTimer.remove();
   385→    if (this.survivalTimerEvent) this.survivalTimerEvent.remove();
   386→    if (this.disconnectTimer) {
   387→      clearTimeout(this.disconnectTimer);
