     1→import { type RealtimeChannel } from '@supabase/supabase-js';
     2→import { supabase } from './supabase';
     3→import {
     4→  BattleEvent,
     5→  type CharAnnouncePayload,
     6→  type ReadyPayload,
     7→  type GameStartPayload,
     8→  type SendPoopPayload,
     9→  type ScoreUpdatePayload,
    10→  type GameOverPayload,
    11→  type RematchRequestPayload,
    12→  type ResultLeavePayload,
    13→} from '../types/BattleTypes';
    14→
    15→type BattlePayloadMap = {
    16→  [BattleEvent.CHAR_ANNOUNCE]: CharAnnouncePayload;
    17→  [BattleEvent.READY]: ReadyPayload;
    18→  [BattleEvent.GAME_START]: GameStartPayload;
    19→  [BattleEvent.SEND_POOP]: SendPoopPayload;
    20→  [BattleEvent.SCORE_UPDATE]: ScoreUpdatePayload;
    21→  [BattleEvent.GAME_OVER]: GameOverPayload;
    22→  [BattleEvent.REMATCH_REQUEST]: RematchRequestPayload;
    23→  [BattleEvent.RESULT_LEAVE]: ResultLeavePayload;
    24→};
    25→
    26→/**
    27→ * Supabase Realtime Broadcast 채널 래퍼
    28→ *
    29→ * ⚠️ Supabase Realtime은 `.on()` 리스너를 `.subscribe()` 전에 등록해야 합니다.
    30→ * 따라서 채널 생성(createRoom/joinRoom) → 리스너 등록(onEvent 등) → 구독(subscribe) 순서로 호출하세요.
    31→ */
    32→export class BattleChannel {
    33→  private channel: RealtimeChannel | null = null;
    34→  private roomCode: string = '';
    35→  private userId: string = '';
    36→
    37→  /** 4자리 랜덤 방 코드 생성 */
    38→  static generateRoomCode(): string {
    39→    const chars = 'REDACTED'; // 혼동 문자(I,O,0,1) 제외
    40→    let code = '';
    41→    for (let i = 0; i < 4; i++) {
    42→      code += chars[Math.floor(Math.random() * chars.length)];
    43→    }
    44→    return code;
    45→  }
    46→
    47→  /** 방 생성 (호스트) — 채널만 생성, subscribe는 별도 호출 */
    48→  createRoom(code: string, userId: string): void { this.initRoom(code, userId, 'battle-room'); }
    49→
    50→  /** 방 참가 (게스트) — 채널만 생성, subscribe는 별도 호출 */
    51→  joinRoom(code: string, userId: string): void { this.initRoom(code, userId, 'battle-room'); }
    52→
    53→  /**
    54→   * 게임 채널 참가 (BattleGameScene 전용)
    55→   * 매칭 채널(battle-room:)과 다른 토픽을 사용하여 Presence 이벤트 혼선 방지
    56→   */
    57→  joinGame(code: string, userId: string): void { this.initRoom(code, userId, 'battle-game'); }
    58→
    59→  /**
    60→   * 결과 채널 참가 (BattleResultScene 전용)
    61→   * 재도전 신호 교환에 사용 (battle-result: 토픽으로 격리)
    62→   */
    63→  joinResult(code: string, userId: string): void { this.initRoom(code, userId, 'battle-result'); }
    64→
    65→  private initRoom(code: string, userId: string, topicPrefix: string): void {
    66→    this.roomCode = code;
    67→    this.userId = userId;
    68→    this.createChannel(topicPrefix);
    69→  }
    70→
    71→  /** 채널 객체만 생성 (구독하지 않음) */
    72→  private createChannel(topicPrefix: string): void {
    73→    this.channel = supabase.channel(`${topicPrefix}:${this.roomCode}`, {
    74→      config: {
    75→        broadcast: { self: false },
    76→        presence: { key: this.userId },
    77→      },
    78→    });
    79→  }
    80→
    81→  /**
    82→   * 리스너 등록 완료 후 호출 — 실제 WebSocket 구독 시작 + Presence track
    83→   * 반드시 onEvent/onPresenceJoin/onPresenceLeave 등록 후에 호출하세요.
    84→   */
    85→  async subscribe(): Promise<void> {
    86→    if (!this.channel) return;
    87→    return new Promise((resolve) => {
    88→      // 10초 타임아웃 — SUBSCRIBED가 오지 않아도 진행 (채널 불안정 시 stuck 방지)
    89→      const timeout = setTimeout(() => {
    90→        console.warn('[BattleChannel] subscribe timeout — forcing channelReady');
    91→        resolve();
    92→      }, 10000);
    93→
    94→      this.channel!.subscribe(async (status) => {
    95→        if (status === 'SUBSCRIBED') {
    96→          clearTimeout(timeout);
    97→          await this.channel!.track({ userId: this.userId, joinedAt: Date.now() });
    98→          resolve();
    99→        } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
   100→          console.warn('[BattleChannel] subscribe failed with status:', status);
   101→          clearTimeout(timeout);
   102→          resolve(); // 에러여도 강제 진행 (무한 대기 방지)
   103→        }
   104→      });
   105→    });
   106→  }
   107→
   108→  /** Broadcast 이벤트 리스너 등록 (subscribe 전에 호출) */
   109→  onEvent<E extends BattleEvent>(event: E, callback: (payload: BattlePayloadMap[E]) => void): void {
   110→    if (!this.channel) return;
   111→    this.channel.on('broadcast', { event }, (msg) => {
   112→      callback(msg.payload as BattlePayloadMap[E]);
   113→    });
   114→  }
   115→
   116→  /** Presence 동기화 — 상대 참가 감지 (subscribe 전에 호출) */
   117→  onPresenceJoin(callback: (userId: string) => void): void {
   118→    if (!this.channel) return;
   119→    this.channel.on('presence', { event: 'join' }, ({ newPresences }) => {
   120→      for (const p of newPresences) {
   121→        const uid = (p as Record<string, unknown>).userId as string;
   122→        if (uid && uid !== this.userId) {
   123→          callback(uid);
   124→        }
   125→      }
   126→    });
   127→  }
   128→
