   140→    this.wpHighlights.clear();
   141→
   142→    // 동기화 전 각성 수치 스냅샷 (동기화 후 변화 감지용)
   143→    this._preSyncDupCounts = new Map(
   144→      CHARACTERS
   145→        .filter(c => this.ownedIds.includes(c.id) && c.grade !== '등급외')
   146→        .map(c => [c.id, getDuplicateCount(c.id)])
   147→    );
   148→
   149→    // 서버 DB와 동기화 — 소유 목록 or 각성 수치가 바뀐 경우 씬 재시작해서 카드 갱신
   150→    syncOwnedCharacters().then(synced => {
   151→      if (!this.scene.isActive()) return;
   152→      const ownedChanged = synced.length !== this.ownedIds.length ||
   153→        synced.some(id => !this.ownedIds.includes(id));
   154→      const awakeChanged = CHARACTERS.some(c =>
   155→        synced.includes(c.id) && c.grade !== '등급외' &&
   156→        getDuplicateCount(c.id) !== this._preSyncDupCounts.get(c.id)
   157→      );
   158→      if (ownedChanged || awakeChanged) this.scene.restart();
   159→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
   160→
   161→    // 배경화면 동기화 (비동기, UI 갱신 없이 진행 — 다음 방문 시 반영)
   162→    syncOwnedWallpapers().then(synced => {
   163→      if (!this.scene.isActive()) return;
   164→      const wpChanged = synced.length !== this.ownedWpIds.length ||
   165→        synced.some(id => !this.ownedWpIds.includes(id));
   166→      if (wpChanged) {
   167→        this.ownedWpIds = synced;
   168→        if (this.activeTab === 'wallpaper') this.rebuildGrid();
   169→      }
   170→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
   171→
   172→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   173→
   174→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
   175→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
   176→    this.bgImage.setDisplaySize(400, 600);
   177→
   178→    // ── 헤더 (고정, depth 10 — 스크롤 카드보다 위) ──────────────────────
   179→    this.add.text(200, 30, '수집', {
   180→      fontSize: '22px',
   181→      color: '#ffffff',
   182→      fontStyle: 'bold',
   183→      stroke: '#000',
   184→      strokeThickness: 4,
   185→    }).setOrigin(0.5).setDepth(10);
   186→
   187→    // ── 탭 버튼 ────────────────────────────────────────────────────────
   188→    const TAB_Y = 60;
   189→    const TAB_W = 160;
   190→    const TAB_H = 30;
   191→
   192→    this.charTabBtnBg = this.add.rectangle(110, TAB_Y, TAB_W, TAB_H, 0x1144bb)
   193→      .setStrokeStyle(1.5, 0x4488ff)
   194→      .setDepth(10)
   195→      .setInteractive({ useHandCursor: true });
   196→    this.charTabLabel = this.add.text(110, TAB_Y, '캐릭터', {
   197→      fontSize: '14px', color: '#ffffff', fontStyle: 'bold',
   198→    }).setOrigin(0.5).setDepth(10);
   199→
   200→    this.wpTabBtnBg = this.add.rectangle(290, TAB_Y, TAB_W, TAB_H, 0x222222)
   201→      .setStrokeStyle(1.5, 0x555555)
   202→      .setDepth(10)
   203→      .setInteractive({ useHandCursor: true });
   204→    this.wpTabLabel = this.add.text(290, TAB_Y, '배경화면', {
   205→      fontSize: '14px', color: '#888888', fontStyle: 'bold',
   206→    }).setOrigin(0.5).setDepth(10);
   207→
   208→    this.charTabBtnBg.on('pointerup', () => {
   209→      if (this.detailPanel) return;
   210→      this.switchTab('character');
   211→    });
   212→    this.wpTabBtnBg.on('pointerup', () => {
   213→      if (this.detailPanel) return;
   214→      this.switchTab('wallpaper');
   215→    });
   216→
   217→    // 구분선
   218→    this.add.rectangle(200, 80, 380, 1, 0x444444).setDepth(10);
   219→
   220→    // 현재 선택 상태 표시
   221→    this.headerNameText = this.add.text(200, 88, `현재: ${selectedDef.name}`, {
   222→      fontSize: '13px',
   223→      color: selectedDef.gradeColor,
   224→      stroke: '#000',
   225→      strokeThickness: 3,
   226→    }).setOrigin(0.5).setDepth(10);
   227→
   228→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   229→    this.cardsContainer = this.add.container(0, 0);
   230→
   231→    this.buildCharacterGrid();
   232→
   233→    // 스크롤 최대 범위 계산 (buildCharacterGrid 내부에서도 설정되지만 여기서도 초기화)
   234→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   235→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   236→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   237→
   238→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   239→    // this.make: display list에 추가되지 않으므로 shutdown 시 직접 정리 필요
   240→    this.maskGfx = this.make.graphics({ x: 0, y: 0 });
   241→    this.maskGfx.fillStyle(0xffffff);
   242→    this.maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   243→    this.cardsContainer.setMask(this.maskGfx.createGeometryMask());
   244→
   245→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   246→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   247→      this.hasPointerDownInScene = true;
   248→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   249→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   250→      this.pointerDownY = p.y;
   251→      this.pointerDownScrollY = this.scrollOffset;
   252→      this.hasDragged = false;
   253→    });
   254→
   255→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   256→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   257→      if (!p.isDown) return;
   258→      const dy = this.pointerDownY - p.y;
   259→      if (Math.abs(dy) > 5) {
   260→        this.hasDragged = true;
   261→        this.scrollOffset = Phaser.Math.Clamp(
   262→          this.pointerDownScrollY + dy,
   263→          0,
   264→          this.maxScrollOffset,
   265→        );
   266→        this.cardsContainer.setY(-this.scrollOffset);
   267→      }
   268→    });
   269→
   270→    this.input.on('pointerup', () => {
   271→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   272→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   273→      this.time.delayedCall(0, () => {
   274→        this.hasDragged = false;
   275→        this.hasPointerDownInScene = false;
   276→      });
   277→    });
   278→
   279→    // 마우스 휠
   280→    this.input.on(
   281→      'wheel',
   282→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   283→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   284→        this.scrollOffset = Phaser.Math.Clamp(
   285→          this.scrollOffset + deltaY * 0.5,
   286→          0,
   287→          this.maxScrollOffset,
   288→        );
   289→        this.cardsContainer.setY(-this.scrollOffset);
   290→      },
   291→    );
   292→
   293→    // ── 고정 UI ─────────────────────────────────────────────────────────
   294→    this.createBackButton();
   295→
   296→    // maskGfx는 display list 외부에 있으므로 씬 종료 시 직접 정리
   297→    this.events.once('shutdown', () => { this.maskGfx.destroy(); });
   298→  }
