   300→  // ── 그리드 빌더 ─────────────────────────────────────────────────────────
   301→
   302→  private buildCharacterGrid() {
   303→    this.cardHighlights.clear();
   304→    this.coresGfx = this.add.graphics();
   305→    CHARACTERS.forEach((char, index) => {
   306→      const col = index % COLS;
   307→      const row = Math.floor(index / COLS);
   308→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   309→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   310→      this.createCharacterCard(char, x, y);
   311→    });
   312→    this.cardsContainer.add(this.coresGfx);
   313→
   314→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   315→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   316→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   317→  }
   318→
   319→  private buildWallpaperGrid() {
   320→    this.wpHighlights.clear();
   321→    // ownedWpIds: create() 초기화 + sync callback에서 직접 갱신
   322→    // selectedWpId: applyWallpaper()가 항상 동기 업데이트 → 재조회 불필요
   323→
   324→    const availableWps = WALLPAPERS.filter(w => AVAILABLE_WP_SET.has(w.id));
   325→    availableWps.forEach((wp, index) => {
   326→      const col = index % WP_COLS;
   327→      const row = Math.floor(index / WP_COLS);
   328→      const x = WP_GRID_LEFT + col * (WP_CARD_W + WP_GAP_X) + WP_CARD_W / 2;
   329→      const y = WP_GRID_TOP + row * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H / 2;
   330→      this.createWallpaperCard(wp, x, y);
   331→    });
   332→
   333→    const totalRows = Math.ceil(availableWps.length / WP_COLS);
   334→    const contentBottom = WP_GRID_TOP + (totalRows - 1) * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H + 10;
   335→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   336→  }
   337→
   338→  private switchTab(tab: 'character' | 'wallpaper') {
   339→    if (this.activeTab === tab) return;
   340→    this.activeTab = tab;
   341→    this.scrollOffset = 0;
   342→    this.hasDragged = false;
   343→    this.cardsContainer.setY(0);
   344→    this.updateBgForTab();
   345→
   346→    // 컨테이너 내 카드 오브젝트 전부 제거
   347→    this.cardsContainer.removeAll(true);
   348→    this.cardHighlights.clear();
   349→    this.wpHighlights.clear();
   350→
   351→    // 탭 버튼 스타일 갱신
   352→    if (tab === 'character') {
   353→      this.charTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   354→      this.charTabLabel.setColor('#ffffff');
   355→      this.wpTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   356→      this.wpTabLabel.setColor('#888888');
   357→
   358→      this.buildCharacterGrid();
   359→
   360→      // 헤더 텍스트 갱신
   361→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   362→      this.headerNameText.setText(`현재: ${def.name}`).setColor(def.gradeColor);
   363→    } else {
   364→      this.wpTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   365→      this.wpTabLabel.setColor('#ffffff');
   366→      this.charTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   367→      this.charTabLabel.setColor('#888888');
   368→
   369→      this.buildWallpaperGrid();
   370→
   371→      // 헤더 텍스트 갱신
   372→      const selWpDef = this.selectedWpId
   373→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   374→        : null;
   375→      this.headerNameText
   376→        .setText(`배경: ${selWpDef?.name ?? '기본'}`)
   377→        .setColor(this.selectedWpId ? WP_ACCENT_HEX : '#888888');
   378→    }
   379→  }
   380→
   381→  /** 현재 탭에 맞게 배경 이미지 업데이트 */
   382→  private updateBgForTab() {
   383→    if (this.activeTab === 'character') {
   384→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   385→      this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   386→    } else {
   387→      const wpDef = this.selectedWpId
   388→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   389→        : null;
   390→      if (wpDef && this.textures.exists(wpDef.bgKey)) {
   391→        this.bgImage.setTexture(wpDef.bgKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   392→      } else {
   393→        // 선택 배경 없음 → 캐릭터 일러스트를 어둡게 처리
   394→        const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   395→        this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(0.2);
   396→      }
   397→    }
   398→  }
   399→
   400→  /** 서버 동기화 후 현재 탭을 내용 갱신 */
   401→  private rebuildGrid() {
   402→    this.cardsContainer.removeAll(true);
   403→    this.cardHighlights.clear();
   404→    this.wpHighlights.clear();
   405→    if (this.activeTab === 'character') {
   406→      this.buildCharacterGrid();
   407→    } else {
   408→      this.buildWallpaperGrid();
   409→    }
   410→  }
