   412→  // ── 배경화면 카드 ────────────────────────────────────────────────────────
   413→
   414→  private createWallpaperCard(wp: BackgroundDef, x: number, y: number) {
   415→    const isOwned = this.ownedWpIds.includes(wp.id);
   416→    const isSelected = this.selectedWpId === wp.id;
   417→
   418→    // 카드 배경
   419→    const cardBg = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0x1a1a2e);
   420→    cardBg.setStrokeStyle(2, isOwned ? WP_ACCENT_INT : 0x333333);
   421→    this.cardsContainer.add(cardBg);
   422→
   423→    // 선택 하이라이트 (흰 테두리)
   424→    const highlight = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0, 0);
   425→    highlight.setStrokeStyle(3, 0xffffff);
   426→    highlight.setVisible(isSelected);
   427→    this.wpHighlights.set(wp.id, highlight);
   428→    this.cardsContainer.add(highlight);
   429→
   430→    // 세로 이미지 (bgKey) — 카드 상단을 채우는 portrait 썸네일
   431→    if (this.textures.exists(wp.bgKey)) {
   432→      const thumb = this.add.image(x, y - 11, wp.bgKey)
   433→        .setDisplaySize(WP_CARD_W - 4, WP_CARD_H - 22);
   434→      if (!isOwned) { thumb.setTint(0x000000); thumb.setAlpha(0.5); }
   435→      this.cardsContainer.add(thumb);
   436→    }
   437→
   438→    // 미보유 자물쇠
   439→    if (!isOwned) {
   440→      const lock = this.add.text(x, y - 8, '🔒', { fontSize: '20px' }).setOrigin(0.5);
   441→      this.cardsContainer.add(lock);
   442→    }
   443→
   444→    // WP 배지 (우상단) — 기본 배경은 '기본', 가챠 배경은 'WP'
   445→    const isDefault = (DEFAULT_WP_IDS as readonly string[]).includes(wp.id);
   446→    const badgeText  = isDefault ? '기본' : 'WP';
   447→    const badgeColor = isDefault ? '#aaaaaa' : WP_ACCENT_HEX;
   448→    const badge = this.add.text(x + WP_CARD_W / 2 - 2, y - WP_CARD_H / 2 + 2, badgeText, {
   449→      fontSize: '9px', color: badgeColor, fontStyle: 'bold',
   450→      backgroundColor: '#000000cc', padding: { x: 3, y: 1 },
   451→    }).setOrigin(1, 0);
   452→    this.cardsContainer.add(badge);
   453→
   454→    // 하단 반투명 바 + 이름
   455→    const barY = y + WP_CARD_H / 2 - 11;
   456→    const bar = this.add.rectangle(x, barY, WP_CARD_W, 22, 0x000000, 0.75);
   457→    this.cardsContainer.add(bar);
   458→    const nameText = this.add.text(x, barY, wp.name, {
   459→      fontSize: '11px',
   460→      color: isOwned ? WP_ACCENT_HEX : '#444444',
   461→      fontStyle: 'bold',
   462→    }).setOrigin(0.5);
   463→    this.cardsContainer.add(nameText);
   464→
   465→    // 클릭 이벤트
   466→    cardBg.setInteractive({ useHandCursor: isOwned });
   467→    if (isOwned) {
   468→      cardBg.on('pointerover', () => cardBg.setFillStyle(0x252540));
   469→      cardBg.on('pointerout',  () => cardBg.setFillStyle(0x1a1a2e));
   470→    }
   471→    cardBg.on('pointerup', () => {
   472→      if (!this.hasDragged && this.hasPointerDownInScene) this.showWallpaperDetail(wp);
   473→    });
   474→  }
