   476→  // ── 배경화면 상세 오버레이 ──────────────────────────────────────────────
   477→
   478→  private showWallpaperDetail(def: BackgroundDef): void {
   479→    this.hideCharacterDetail();
   480→
   481→    // 패널 열기 직후 고스트 mouseup 방지
   482→    this.input.enabled = false;
   483→    this.time.delayedCall(150, () => { this.input.enabled = true; });
   484→
   485→    const isOwned = this.ownedWpIds.includes(def.id);
   486→    const isSelected = this.selectedWpId === def.id;
   487→
   488→    const panel = this.add.container(0, 0).setDepth(300);
   489→    this.detailPanel = panel;
   490→
   491→    // 클릭 차단
   492→    const blocker = this.add.rectangle(200, 300, 400, 600, 0x000000, 0).setInteractive();
   493→    panel.add(blocker);
   494→
   495→    // 배경화면 전체화면 미리보기
   496→    if (this.textures.exists(def.bgKey)) {
   497→      const bg = this.add.image(200, 300, def.bgKey).setDisplaySize(400, 600);
   498→      panel.add(bg);
   499→    } else {
   500→      const fallback = this.add.rectangle(200, 300, 400, 600, 0x050515);
   501→      const hint = this.add.text(200, 300, '이미지 없음\n(에셋 추가 필요)', {
   502→        fontSize: '16px', color: '#666666', align: 'center',
   503→      }).setOrigin(0.5);
   504→      panel.add(fallback);
   505→      panel.add(hint);
   506→    }
   507→
   508→    // 하단 그라디언트 오버레이
   509→    const grad = this.add.graphics();
   510→    grad.fillGradientStyle(0x000000, 0x000000, 0x000000, 0x000000, 0, 0, 0.8, 0.8);
   511→    grad.fillRect(0, 380, 400, 220);
   512→    panel.add(grad);
   513→
   514→    // ✕ 닫기 버튼
   515→    const closeBg = this.add.circle(372, 38, 22, 0x000000, 0.55)
   516→      .setInteractive({ useHandCursor: true });
   517→    const closeBtn = this.add.text(372, 38, '✕', { fontSize: '18px', color: '#cccccc' }).setOrigin(0.5);
   518→    closeBg.on('pointerover', () => { closeBg.setFillStyle(0x333333, 0.8); closeBtn.setColor('#ffffff'); });
   519→    closeBg.on('pointerout',  () => { closeBg.setFillStyle(0x000000, 0.55); closeBtn.setColor('#cccccc'); });
   520→    closeBg.on('pointerup',   () => this.hideCharacterDetail());
   521→    panel.add(closeBg);
   522→    panel.add(closeBtn);
   523→
   524→    // 이름
   525→    panel.add(this.add.text(24, 450, def.name, {
   526→      fontSize: '26px', color: '#ffffff', fontStyle: 'bold',
   527→      stroke: '#000000', strokeThickness: 5,
   528→    }));
   529→    panel.add(this.add.text(24, 494, def.description, {
   530→      fontSize: '12px', color: '#aaaaaa',
   531→      stroke: '#000000', strokeThickness: 3,
   532→      wordWrap: { width: 350 },
   533→    }));
   534→
   535→    // ── 버튼 2개 ──
   536→    const BTN_Y = 562;
   537→    const BTN_W = 168;
   538→    const BTN_H = 42;
   539→
   540→    if (isOwned) {
   541→      if (!isSelected) {
   542→        // [적용하기]
   543→        const applyBg = this.add.rectangle(108, BTN_Y, BTN_W, BTN_H, 0x115511)
   544→          .setStrokeStyle(2, WP_ACCENT_INT)
   545→          .setInteractive({ useHandCursor: true });
