   609→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   610→    const isOwned = this.ownedIds.includes(char.id);
   611→    const isSelected = this.selectedId === char.id;
   612→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   613→
   614→    // 카드 배경
   615→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   616→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   617→    this.cardsContainer.add(cardBg);
   618→
   619→    // 선택 하이라이트
   620→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   621→    highlight.setStrokeStyle(3, 0xffffff);
   622→    highlight.setVisible(isSelected);
   623→    this.cardHighlights.set(char.id, highlight);
   624→    this.cardsContainer.add(highlight);
   625→
   626→    // 캐릭터 이미지
   627→    const img = this.add.image(x, y - 12, char.imageKey);
   628→    img.setDisplaySize(58, 85);
   629→    this.cardsContainer.add(img);
   630→
   631→    if (!isOwned) {
   632→      img.setTint(0x000000);
   633→      img.setAlpha(0.6);
   634→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   635→      this.cardsContainer.add(lock);
   636→    }
   637→
   638→    // 등급 배지
   639→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   640→      fontSize: '9px',
   641→      color: char.gradeColor,
   642→      fontStyle: 'bold',
   643→      backgroundColor: '#000000cc',
   644→      padding: { x: 3, y: 1 },
   645→    }).setOrigin(1, 0);
   646→    this.cardsContainer.add(badge);
   647→
   648→    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
   649→    if (isOwned && char.grade !== '등급외') {
   650→      const dupCount   = getDuplicateCount(char.id);
   651→      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
   652→      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;
   653→
   654→      for (let i = 0; i < CORE_COUNT; i++) {
   655→        const cx = x + (i - 2) * CORE_GAP;
   656→        if (i < awakeLevel) {
   657→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
   658→          this.coresGfx.fillStyle(gradeColorInt, 0.25);
   659→          this.coresGfx.fillCircle(cx, coreY, CORE_GLOW_RADIUS);
   660→          this.coresGfx.fillStyle(gradeColorInt, 1);
   661→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   662→          this.coresGfx.fillStyle(0xffffff, 0.55);
   663→          this.coresGfx.fillCircle(cx - 1, coreY - 1, CORE_HIGHLIGHT_R);
   664→        } else {
   665→          // 빈 코어: 어두운 원 + 얇은 테두리
   666→          this.coresGfx.fillStyle(0x111111, 1);
   667→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   668→          this.coresGfx.lineStyle(1, gradeColorInt, 0.35);
   669→          this.coresGfx.strokeCircle(cx, coreY, CORE_INNER_RADIUS);
   670→        }
   671→      }
   672→    }
   673→
   674→    // 캐릭터 이름
   675→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   676→      fontSize: '12px',
   677→      color: isOwned ? '#ffffff' : '#555555',
   678→      fontStyle: 'bold',
   679→    }).setOrigin(0.5);
   680→    this.cardsContainer.add(nameText);
   681→
   682→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   683→    cardBg.setInteractive({ useHandCursor: isOwned });
   684→
   685→    if (isOwned) {
   686→      cardBg.on('pointerover', () => {
   687→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   688→      });
   689→      cardBg.on('pointerout', () => {
   690→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   691→      });
   692→    }
   693→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
   694→    cardBg.on('pointerup', () => {
   695→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
   696→    });
   697→  }
