   851→        videoObj!.setVisible(false);
   852→        illust.setVisible(true);
   853→      };
   854→      videoObj.setInteractive({ useHandCursor: true });
   855→      videoObj.on('pointerup', stopVideo);
   856→      videoObj.on('complete', stopVideo);
   857→    }
   858→  }
