   860→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   861→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   862→    const W = 400, H = 600;
   863→    vid.setDisplaySize(W, H);
   864→
   865→    const applyContain = () => {
   866→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   867→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   868→      const nw = el?.videoWidth  || 0;
   869→      const nh = el?.videoHeight || 0;
   870→      if (nw > 0 && nh > 0) {
   871→        const scale = Math.max(W / nw, H / nh);
   872→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   873→      }
   874→    };
   875→
   876→    vid.once('play', applyContain);
   877→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   878→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   879→  }
   880→
   881→  private hideCharacterDetail(): void {
   882→    // fitVideoToPanel의 pending 타이머 취소
   883→    for (const t of this.fitVideoTimers) t.remove();
   884→    this.fitVideoTimers = [];
   885→
   886→    // 비디오 명시 정지 및 HTMLVideoElement src 해제
   887→    if (this.detailVideo) {
   888→      this.detailVideo.stop();
   889→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   890→      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
   891→      if (el) { el.src = ''; }
   892→      this.detailVideo = null;
   893→    }
   894→
   895→    this.hideInfoPanel();
   896→    this.detailPanel?.destroy();
   897→    this.detailPanel = null;
   898→  }
