   905→  private showInfoPanel(def: CharacterDef): void {
   906→    this.hideInfoPanel();
   907→
   908→    // 패널 열기 직후 고스트 mouseup 방지
   909→    this.input.enabled = false;
   910→    this.time.delayedCall(150, () => { this.input.enabled = true; });
   911→
   912→    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   913→    const panel = this.add.container(0, 0).setDepth(400);
   914→    this.infoPanel = panel;
   915→
   916→    // ── 각성 보너스 계산 ──────────────────────────────────────────────
   917→    const dupCount   = getDuplicateCount(def.id);
   918→    const awakeLevel = getAwakeningLevel(def.grade, dupCount);
   919→    const awakeBonusLines: string[] = [];
   920→    if (def.grade !== '등급외') {
   921→      if (awakeLevel >= 1) {
   922→        const spd = def.id === 'maehwa' ? 5 : def.grade === 'UR' ? 15 : def.grade === 'SR' ? 10 : 5;
   923→        awakeBonusLines.push(`★1 각성: 이동속도 +${spd} px/s`);
   924→      }
   925→      if (awakeLevel >= 2) {
   926→        if (def.id === 'maehwa') {
   927→          awakeBonusLines.push('★2 각성: 특수 똥 수집 시 +5점');
   928→        } else {
   929→          const spd = def.grade === 'UR' ? 20 : def.grade === 'SR' ? 15 : 10;
   930→          awakeBonusLines.push(`★2 각성: 이동속도 +${spd} px/s (누적)`);
   931→        }
   932→      }
   933→    }
   934→    const awakeBonusText = awakeBonusLines.join('\n');
   935→
   936→    // 반투명 배경 (클릭 시 닫기)
   937→    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.80)
   938→      .setInteractive();
   939→    overlay.on('pointerup', () => this.hideInfoPanel());
   940→    panel.add(overlay);
   941→
   942→    // ── 카드 크기 계산 (텍스트 높이 선측정) ─────────────────────────
   943→    const B_LEFT = 30;
   944→    const CARD_W = 370;
   945→    const WRAP_W = CARD_W - 40; // 좌(15px)·우(25px) 여백 제외한 실제 텍스트 폭
   946→    const HEADER_H = 60;  // 스프라이트+이름+구분선 영역
