   304→      // ① 중복 캐릭터 각성 카운트 업데이트
   305→      result.characters.filter(c => !c.isNew).forEach(c => {
   306→        setDuplicateCount(c.id, getDuplicateCount(c.id) + 1);
   307→      });
   308→      // ① 신규 배경화면 즉시 저장 (sync 실패 대비 fallback)
   309→      this.wpResults.filter(w => w.isNew).forEach(w => addOwnedWallpaper(w.id));
   310→      // ② 서버 DB 전체 동기화 (비동기, 에러 로그만)
   311→      syncOwnedCharacters().catch(e => console.error('[GachaScene] syncOwnedCharacters 실패:', e));
   312→      syncOwnedWallpapers().catch(e => console.error('[GachaScene] syncOwnedWallpapers 실패:', e));
   313→
   314→      // ② 터미널 애니메이션 (UR이면 중반부터 빨간 에러 스타일로 전환)
   315→      const isUR = result.video === 'red'
   316→      this.skipTerminal = false;
   317→      this.clearUI();
   318→      this.add.rectangle(200, 300, 400, 600, 0x000000);
   319→      this.drawTerminalChrome(false); // 항상 초록으로 시작
   320→      this.addSkipButton(() => { this.skipTerminal = true; });
   321→      await this.runTerminalAnimation(count, isUR);
   322→      this.skipTerminal = false;
   323→
   324→      // ③ 캐릭터별 개인 영상 + 배경화면 이미지 동적 로드 → 리빌
   325→      await Promise.all([
   326→        this.loadCharVideos(result.characters.map(c => c.id)),
   327→        this.loadWallpaperBgs(this.wpResults.map(w => w.id)),
   328→      ]);
   329→
   330→      this.showNextReveal();
   331→    } catch {
   332→      if (!this.scene.isActive()) return;
   333→      await this.typeLines([
   334→        '> CONNECTION ERROR',
   335→        '> Retrying in 3s...',
   336→      ], 30);
   337→      this.time.delayedCall(3000, () => this.buildLobby());
   338→    }
   339→  }
