   390→  /** 영상 원본 비율을 유지하면서 캔버스 안에 꽉 차게 (contain) */
   391→  private fitVideoToCanvas(vid: Phaser.GameObjects.Video, canvasW: number, canvasH: number) {
   392→    vid.setDisplaySize(canvasW, canvasH); // 초기값
   393→
   394→    const applyContain = () => {
   395→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   396→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   397→      const nw = el?.videoWidth  || 0;
   398→      const nh = el?.videoHeight || 0;
   399→      if (nw > 0 && nh > 0) {
   400→        const scale = Math.max(canvasW / nw, canvasH / nh);
   401→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   402→      }
   403→    };
   404→
   405→    vid.once('play', applyContain);
   406→    this.time.delayedCall(100, applyContain);
   407→    this.time.delayedCall(500, applyContain);
   408→  }
