   573→  private showNextReveal() {
   574→    if (this.revealItemIndex >= this.revealItems.length) {
   575→      this.showSummary();
   576→      return;
   577→    }
   578→
   579→    const item = this.revealItems[this.revealItemIndex];
   580→
   581→    // 배경화면 슬롯이면 배경 리빌 카드로 분기
   582→    if (item.kind === 'wallpaper') {
   583→      const def = getWallpaperDef(item.data.id);
   584→      this.showWallpaperRevealCard(item.data, def);
   585→      return;
   586→    }
   587→
   588→    const pulled = item.data;
   589→    const def = getCharacterDef(pulled.id);
   590→
   591→    const { width, height } = this.cameras.main;
   592→    this.clearUI();
   593→
   594→    const vidKey = `vid_${pulled.id}`;
   595→    if (this.cache.video.exists(vidKey)) {
   596→      const vid = this.add.video(width / 2, height / 2, vidKey);
   597→      vid.play(false);
   598→      this.fitVideoToCanvas(vid, width, height);
   599→
   600→      let proceeded = false;
   601→      const proceed = () => {
   602→        if (proceeded) return;
   603→        proceeded = true;
   604→        this.input.off('pointerdown', proceed);
   605→        if (vid.active) vid.destroy();
   606→        this.showRevealCard(pulled, def);
   607→      };
   608→
   609→      this.addSkipButton(() => {
   610→        if (proceeded) return;
   611→        proceeded = true;
   612→        this.input.off('pointerdown', proceed);
   613→        if (vid.active) vid.destroy();
   614→        // 10연차: 영상 스킵 시 남은 리빌 전체 건너뛰고 결과 화면으로
   615→        if (this.revealItems.length > 1) {
   616→          this.showSummary();
   617→        } else {
   618→          this.showRevealCard(pulled, def);
   619→        }
   620→      });
   621→      vid.on('complete', proceed);
   622→      this.time.delayedCall(10000, proceed); // failsafe
   623→      this.input.once('pointerdown', proceed); // 탭으로 스킵
   624→    } else {
   625→      this.showRevealCard(pulled, def);
   626→    }
   627→  }
