   897→  private typeLines(lines: string[], delay = 40, color = '#00ff41'): Promise<void> {
   898→    return lines.reduce(
   899→      (p, line) => p.then(() => this.typeLine(line, delay, color)),
   900→      Promise.resolve()
   901→    );
   902→  }
   903→
   904→  private typeLine(text: string, charDelay = 40, color = '#00ff41'): Promise<void> {
   905→    return new Promise(resolve => {
   906→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   907→
   908→      // 최대 6줄 유지 (스크롤 효과)
   909→      if (this.terminalTexts.length >= 6) {
   910→        this.terminalTexts.shift()?.destroy();
   911→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   912→      }
   913→
   914→      const y = 276 + this.terminalTexts.length * 22;
   915→      const t = this.add.text(24, y, '', {
   916→        fontSize: '13px', color, fontFamily: 'monospace',
   917→      });
   918→      this.terminalTexts.push(t);
   919→
   920→      let i = 0;
   921→      const ev = this.time.addEvent({
   922→        delay: charDelay,
   923→        repeat: text.length,
   924→        callback: () => {
   925→          if (!this.scene.isActive() || this.skipTerminal) { ev.destroy(); resolve(); return; }
   926→          t.setText(text.substring(0, i + 1));
   927→          i++;
   928→          if (i > text.length) { ev.destroy(); resolve(); }
   929→        },
   930→      });
   931→    });
   932→  }
   933→
   934→  private progressBar(duration: number, color = '#00ff41'): Promise<void> {
   935→    return new Promise(resolve => {
   936→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   937→
   938→      if (this.terminalTexts.length >= 6) {
   939→        this.terminalTexts.shift()?.destroy();
   940→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   941→      }
   942→
   943→      const y = 276 + this.terminalTexts.length * 22;
   944→      const bar = this.add.text(24, y, '> [          ]  0%', {
   945→        fontSize: '13px', color, fontFamily: 'monospace',
   946→      });
   947→      this.terminalTexts.push(bar);
   948→
   949→      let step = 0;
   950→      const steps = 10;
   951→      const ev = this.time.addEvent({
   952→        delay: duration / steps,
   953→        repeat: steps - 1,
   954→        callback: () => {
   955→          step++;
   956→          bar.setText(`> [${'█'.repeat(step)}${' '.repeat(steps - step)}] ${step * 10}%`);
   957→          if (this.skipTerminal || step >= steps) { ev.destroy(); resolve(); }
   958→        },
   959→      });
   960→    });
   961→  }
   962→
   963→  private sleep(ms: number): Promise<void> {
   964→    return new Promise(resolve => {
   965→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   966→      this.time.delayedCall(ms, resolve);
   967→    });
   968→  }
