   295→  /** 내 RP/티어 조회 — localStorage 캐시로 즉시 표시 후 API 응답으로 갱신 */
   296→  private async fetchMyRating() {
   297→    // 1) 캐시 즉시 반영
   298→    const cached = getCachedMyRating();
   299→    if (cached) {
   300→      this.cachedMyRp = cached.rp;
