   305→    // 2) API 호출 후 캐시 갱신 + UI 업데이트
   306→    try {
   307→      const stats = await getMyRating();
   308→      if (stats) {
   309→        this.cachedMyRp = stats.ratingPoints;
   310→        this.cachedMyRank = stats.rank;
   311→        setCachedMyRating(stats.ratingPoints, stats.rank);
