   344→  private async startRankedMatchmaking() {
   345→    if (this.isMatchmaking || this.battleChannel) return;
   346→    this.isMatchmaking = true;
   347→
   348→    try {
   349→      // 인증 보장 (익명 로그인 포함)
   350→      this.userId = await getAuthUserId();
   351→    } catch {
   352→      this.isMatchmaking = false;
   353→      return;
   354→    }
   355→
   356→    this.showRankedWaiting();
   357→
   358→    let result: MatchResult;
   359→    try {
   360→      result = await findOrCreateMatch(this.userId);
   361→    } catch {
   362→      this.isMatchmaking = false;
   363→      this.showMenu();
   364→      return;
   365→    }
   366→
   367→    if (result.status === 'matched') {
   368→      this.onRankedMatchFound(result);
   369→      return;
   370→    }
   371→
   372→    // 대기 중 — 2초마다 폴링
   373→    this.rankMatchPollTimer = setInterval(async () => {
   374→      try {
   375→        const poll = await pollMatchStatus(this.userId);
   376→        if (poll?.status === 'matched') {
   377→          this.clearRankedPoll();
   378→          this.onRankedMatchFound(poll);
   379→        }
   380→      } catch {
   381→        // 네트워크 오류 시 계속 재시도
   382→      }
   383→    }, 2000);
   384→  }
