   785→  private setupChannelListeners() {
   786→    if (!this.battleChannel) return;
   787→
   788→    // Presence join — 상대 입장 감지 → 내 캐릭터 재알림 + 호스트는 준비 버튼 표시
   789→    this.battleChannel.onPresenceJoin(() => {
   790→      // 늦게 접속한 상대가 내 캐릭터를 모를 수 있으므로 재전송
   791→      this.battleChannel?.sendCharAnnounce(getSafeSelectedCharacter());
