   838→    // UI 갱신: 상대 대기 화면
   839→    this.clearUI();
   840→    this.ui(this.add.text(200, 270, '✅ 준비 완료!', {
   841→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   842→      stroke: '#000', strokeThickness: 4,
   843→    }).setOrigin(0.5));
   844→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   845→      fontSize: '16px', color: '#ffffff',
   846→      stroke: '#000', strokeThickness: 3,
   847→    }).setOrigin(0.5));
   848→
   849→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
