   880→  private showCountdown() {
   881→    this.clearUI();
   882→
   883→    let count = 3;
   884→    const countText = this.ui(this.add.text(200, 280, `${count}`, {
   885→      fontSize: '90px', color: '#ff4444', fontStyle: 'bold',
   886→      stroke: '#000', strokeThickness: 8,
   887→    }).setOrigin(0.5));
   888→
   889→    const timer = this.time.addEvent({
   890→      delay: 1000,
   891→      callback: () => {
   892→        count--;
   893→        if (count > 0) {
   894→          (countText as Phaser.GameObjects.Text).setText(`${count}`);
   895→        } else {
   896→          (countText as Phaser.GameObjects.Text).setText('GO!');
   897→          (countText as Phaser.GameObjects.Text).setColor('#00ff00');
   898→          timer.remove();
   899→          this.time.delayedCall(500, () => this.goToBattle());
   900→        }
   901→      },
   902→      repeat: 2,
   903→    });
   904→  }
