   457→    this.cardsContainer.add(bar);
   458→    const nameText = this.add.text(x, barY, wp.name, {
   459→      fontSize: '11px',
   460→      color: isOwned ? WP_ACCENT_HEX : '#444444',
   461→      fontStyle: 'bold',
   462→    }).setOrigin(0.5);
   463→    this.cardsContainer.add(nameText);
   464→
   465→    // 클릭 이벤트
   466→    cardBg.setInteractive({ useHandCursor: isOwned });
