   163→  private advanceSlide() {
   164→    if (!this.slideshowActive || !this.scene.isActive()) return;
   165→
   166→    const nextIndex = (this.slideshowIndex + 1) % SLIDESHOW_IDS.length;
   167→    const nextDef = getCharacterDef(SLIDESHOW_IDS[nextIndex]);
   168→
   169→    // 현재/다음 레이어 결정
   170→    const current  = this.slideshowIsA ? this.slideshowBgA : this.slideshowBgB;
   171→    const incoming = this.slideshowIsA ? this.slideshowBgB : this.slideshowBgA;
   172→    if (!current || !incoming) return;
   173→
   174→    // 다음 일러스트를 incoming 레이어에 세팅
   175→    incoming.setTexture(nextDef.illustKey).setAlpha(0);
   176→
   177→    // 상태 + 텍스트를 일러스트 전환 시작과 동시에 즉시 교체
   178→    this.slideshowIsA = !this.slideshowIsA;
   179→    this.slideshowIndex = nextIndex;
   180→    this.updateSlideshowText(nextDef);
   181→
   182→    // crossfade: 현재 fade-out, 다음 fade-in
   183→    this.tweens.add({ targets: current,  alpha: 0, duration: 600, ease: 'Sine.easeInOut' });
   184→    this.tweens.add({ targets: incoming, alpha: 1, duration: 600, ease: 'Sine.easeInOut' });
   185→  }
